 const day=['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'][(state.day-1)%7],hour=Math.floor(state.hour/60)%24,greet=hour<5?'Late night':hour<12?'Good morning':hour<18?'Good afternoon':'Good evening';
 const wx=window.ChinaLifeWorld?.weatherFor?.(state.city,state.day)||'clear',wxText={clear:hour>=6&&hour<19?'☀️ Sunny':'🌙 Clear night',cloudy:'⛅ Cloudy',rain:'🌧 Rain',snow:'❄️ Snow'}[wx];
