 const section=(title,ids)=>{const list=ids.filter(id=>all[id]&&!placed.has(id)&&rest.concat(focus).includes(id));list.forEach(id=>placed.add(id));return list.length?'<section class="cl-group"><h4>'+title+'</h4><div class="phone-apps">'+list.map(app).join('')+'</div></section>':''};
 const sections=groups.map(([t,ids])=>section(t,ids)).join('')+section('More',Object.keys(all));
 $('phoneContent').innerHTML='<div class="cl-phone"><header class="cl-hero"><div class="cl-hero-top"><span>'+escapeHTML((cityData[state.city]?.han||'')+' '+state.city)+'</span><span>'+wxText+' · '+timeText()+'</span></div><b class="cl-greet">'+greet+(state.name?', '+escapeHTML(state.name.split(' ')[0]):'')+'</b><small class="cl-date">'+day+' · Day '+state.day+'</small>'
