function eventScreen(id){const cloud=window.ChinaLifeCloud,e=(cloud?.events||[]).find(x=>String(x.id)===String(id));if(!e)return toast('This event has ended.');const venue=L.find(p=>p[0]===e.place),here=!e.place||state.place===e.place,left=Math.max(0,Math.round((e.ends_at-Date.now())/6e4));
 screen('🎉 '+escapeHTML(e.title),(venue?venue[3]+' '+escapeHTML(venue[1])+' · ':'')+'Ends in '+(left>=60?Math.floor(left/60)+'h ':'')+left%60+'m',(e.body?'<p>'+escapeHTML(e.body)+'</p>':'')+(e.joined?'<p><b>✓ You joined this event.</b></p>':here?action('eventJoin','🎉 Join event'+(e.reward?' · +¥'+e.reward.toLocaleString():''),'Once per player'):action('eventGo','Go to '+escapeHTML(venue[1]),'Join when you arrive'))+(e.link?'<a class="soft-btn" href="'+escapeHTML(e.link)+'" target="_blank" rel="noopener noreferrer">More info</a>':''));
 if($('eventGo'))$('eventGo').onclick=()=>{$('activityDialog').close();select(e.place)};
 if($('eventJoin'))$('eventJoin').onclick=async()=>{$('eventJoin').disabled=true;try{await cloud.joinEvent(e.id);state.xp+=25;finish('🎉 You joined '+e.title+(e.reward?' · +¥'+e.reward.toLocaleString():''));}catch(err){toast(err.message)}finally{if($('eventJoin'))$('eventJoin').disabled=false}}}
