  +'<form id="apBadge" class="admin-form"><input id="apBadgeIcon" class="name-input" maxlength="8" placeholder="Icon, e.g. 🏮" required><input id="apBadgeName" class="name-input" maxlength="60" placeholder="Badge name, e.g. Lantern Festival 2026" required><button class="primary-btn">Award badge</button></form>'
  +'<h3>Rank privileges</h3><form id="apSuspend" class="admin-form"><input id="apDays" type="number" min="0" max="365" step="1" class="name-input" placeholder="Days (0 lifts it)" required><input id="apSusNote" class="name-input" maxlength="200" placeholder="Reason (required to suspend)"><button class="primary-btn">'+(susp?'Update suspension':'Suspend rank privileges')+'</button></form><p class="fine-print">While suspended: no rank rewards, no rank perks, hidden from the leaderboard.</p>'
