 $('apRank').onsubmit=ev=>{ev.preventDefault();const n=Number($('apRankSel').value);if(confirm('Set '+d.name+' to '+ranks[n][1]+'?'))run('set_rank',{rank:n,note:$('apRankNote').value.trim()},'Rank set.')};
 $('apBadge').onsubmit=ev=>{ev.preventDefault();run('award_badge',{icon:$('apBadgeIcon').value.trim(),name:$('apBadgeName').value.trim()},'Badge awarded.')};
 $('apSuspend').onsubmit=ev=>{ev.preventDefault();const days=Number($('apDays').value);if(!Number.isInteger(days))return toast('Enter whole days.');run('suspend_rank',{days,note:$('apSusNote').value.trim()},days?'Rank privileges suspended.':'Suspension lifted.')};
