// Dice table: roll two dice against the house; higher doubles the bet, a tie returns it. 10 rolls a day.
function diceScreen(result=''){const rolls=state.dice?.day===state.day?state.dice.count:0;screen('🎲 Dice table','Roll higher than the house to double your bet · '+(10-rolls)+' rolls left today',(result?'<p class="dice-result">'+result+'</p>':'')+[50,200,1000].map(b=>action('dice-'+b,'Bet ¥'+b.toLocaleString(),'Win ¥'+(b*2).toLocaleString()+' · tie returns your bet')).join('')+'<p class="fine-print">Game money only. No real money is involved.</p>');
 [50,200,1000].forEach(b=>$('dice-'+b).onclick=()=>{const used=state.dice?.day===state.day?state.dice.count:0;if(used>=10)return toast('The table is closed for you today. Come back tomorrow.');if(state.money<b)return earnScreen('You need ¥'+b+' to play.');state.dice={day:state.day,count:used+1};const roll=()=>1+Math.floor(Math.random()*6),me=roll()+roll(),house=roll()+roll();const delta=me>house?b:me<house?-b:0;state.money+=delta;state.xp+=2;finish('🎲 You rolled '+me+', the house rolled '+house+(delta>0?' · you win ¥'+b.toLocaleString():delta<0?' · you lose ¥'+b.toLocaleString():' · tie'));diceScreen('You '+me+' · House '+house+' — '+(delta>0?'🎉 +¥'+b.toLocaleString():delta<0?'−¥'+b.toLocaleString():'Tie'))})}
