// Hafrik HQ: players apply for real Hafrik services; admins review the applications in the panel.
const appStatus={pending:'⏳ Waiting for review',approved:'✅ Approved · we will contact you',declined:'❌ Not available right now'};
async function hqScreen(service=null){const signedIn=window.ChinaLifeCloud?.signedIn;
 if(!signedIn){screen('🏢 Hafrik HQ','Sign in with Hafrik to apply for services.',action('hqSignIn','Sign in with Hafrik','Your applications are linked to your Hafrik account'));$('hqSignIn').onclick=()=>window.ChinaLifeCloud?.open();return}
 screen('🏢 Hafrik HQ','Apply for Hafrik services. Our team replies on WhatsApp, WeChat or email.','<p id="hqBody">Loading…</p>');
 try{const r=await window.ChinaLifeAuth.request('/chinalife/applications.php','GET'),d=r.data||r;if(!$('hqBody'))return;const s=d.services||{};
  if(service&&s[service])return hqApply(service,s[service]);
  $('hqBody').outerHTML='<div>'+(d.applications.length?'<h3>Your applications</h3>'+d.applications.map(a=>'<p class="journal-item">'+escapeHTML((s[a.service]?.icon||'')+' '+(s[a.service]?.title||a.service))+' · '+(appStatus[a.status]||escapeHTML(a.status))+(a.admin_note?' · '+escapeHTML(a.admin_note):'')+'</p>').join(''):'')
   +'<h3>Services</h3>'+Object.entries(s).map(([id,x])=>action('svc-'+id,x.icon+' '+escapeHTML(x.title),escapeHTML(x.detail))).join('')+'</div>';
  Object.entries(s).forEach(([id,x])=>$('svc-'+id).onclick=()=>hqApply(id,x))}catch(e){if($('hqBody'))$('hqBody').textContent=e.message}}
function hqApply(id,x){screen(x.icon+' '+escapeHTML(x.title),escapeHTML(x.detail),'<form id="hqForm" class="admin-form"><label>Your name<input id="hqName" class="name-input" maxlength="80" required value="'+escapeHTML(state.name||'')+'"></label><label>WhatsApp, WeChat ID or email<input id="hqContact" class="name-input" maxlength="80" required placeholder="How we reach you"></label><label>City<input id="hqCity" class="name-input" maxlength="40" value="'+escapeHTML(state.city)+'"></label><label>Tell us what you need<textarea id="hqMessage" class="name-input" maxlength="600" placeholder="Optional"></textarea></label><p class="fine-print">Your details go only to the Hafrik team for this request.</p><button class="primary-btn">Send application</button></form>'+action('hqBack','← All services',''));
 $('hqBack').onclick=()=>hqScreen();
 $('hqForm').onsubmit=async ev=>{ev.preventDefault();try{await window.ChinaLifeAuth.request('/chinalife/applications.php','POST',{service:id,name:$('hqName').value.trim(),contact:$('hqContact').value.trim(),city:$('hqCity').value.trim(),message:$('hqMessage').value.trim()});state.xp+=10;finish('🏢 Application sent: '+x.title+'. The Hafrik team will contact you.');hqScreen()}catch(e){toast(e.message)}}}
