 const owned=i=>i.slot==='car'?g.owned.includes(i.id):w.owned.includes(i.id),wearing=i=>i.slot==='car'?g.active===i.id:i.slot==='acc'?w.wearing.acc.includes(i.id):w.wearing[i.slot]===i.id;
