function setRanks(list){if(!Array.isArray(list)||list.length<2||list.some((r,i)=>!Number.isInteger(r?.xp)||typeof r.name!=='string'||typeof r.icon!=='string'||!Number.isInteger(r.reward)||(i?r.xp<=list[i-1].xp:r.xp!==0)))return;const next=list.map(r=>[r.xp,r.name,r.icon,r.reward]);if(JSON.stringify(next)===JSON.stringify(ranks))return;ranks.splice(0,ranks.length,...next);if(state.created)render()}
