  state=JSON.parse(JSON.stringify(state));state.student=studentProfile(onboard.start);state.story={version:1,phase:'arrival',index:onboard.start==='outside'?0:1,season:'winter'};state.logs.unshift('Your student story begins.');studentSetupMode='create';save();$('onboarding').close();render();studentStory();return;
