const allSkills=['Chinese','Study','Digital','Creativity','Cooking','Music','Fitness','Social','Network'],skillIcons={Chinese:'🀄',Study:'📖',Digital:'💻',Creativity:'🎨',Cooking:'🥟',Music:'🎧',Fitness:'💪',Social:'💬',Network:'🤝'};
function skillsScreen(){const teach=skill=>L.filter(p=>inCity(p[0])&&p[7].some(a=>a[1].includes('trains '+skill)));screen('Learn','Take courses and practise at places across Shenyang. Every 100 points raises a skill level and unlocks new jobs.','<h3>Certificates</h3><div class="rank-list">'+certificates.map(([id,name,skill,lv,reward])=>{const has=(state.certs||[]).includes(id);return '<div class="'+(has?'reached':'')+'"><span>'+(has?'🎓':'📜')+'</span><b>'+name+'</b><small>'+skill+' level '+lv+' · ¥'+reward.toLocaleString()+'</small></div>'}).join('')+'</div><h3>Skills</h3>'+allSkills.map(k=>'<div class="skill-item"><b>'+skillIcons[k]+' '+k+' · Level '+(state.skills[k]||1)+'</b><progress max="100" value="'+(state.skillXP[k]||0)+'"></progress><span>'+(state.skillXP[k]||0)+'/100 to next level</span><div class="learn-places">'+teach(k).map(p=>'<button data-learn="'+p[0]+'">'+p[3]+' '+escapeHTML(p[1])+'</button>').join('')+'</div></div>').join(''));$('activityContent').querySelectorAll('[data-learn]').forEach(b=>b.onclick=()=>{$('activityDialog').close();select(b.dataset.learn)})}
const contacts=[['mei','Mei','campus','Student · enjoys language exchanges'],['tunde','Tunde','business','Founder · building a small studio'],['amina','Amina','ef','New arrival · looking for a study partner'],['leo','Leo','gym','Trainer · always ready for basketball']];
function peopleScreen(){screen('People in your city','Four simulated characters, each with a story. Visit their usual spot to talk.',contacts.map(c=>action('friend-'+c[0],c[1]+' · '+((state.friends[c[0]]||0)>=60?'Close friend':(state.friends[c[0]]||0)>=30?'Friend':'Acquaintance'),c[3]+' · Bond '+(state.friends[c[0]]||0)+'/100')).join(''));contacts.forEach(c=>$('friend-'+c[0]).onclick=()=>personScreen(c[0]))}
const dialogue={mei:{intro:'I came here to study engineering. At first, I was too nervous to speak in class. Language exchanges helped.',skill:'Chinese',answers:['Let’s practise a phrase together. Getting it wrong is part of learning.','The EFH language class is a good place to start. A little practice each day adds up.','I miss home too sometimes. Sharing the small wins makes this city feel less lonely.']},tunde:{intro:'I’m building a creative studio. Finding my first client was harder than setting up the business.',skill:'Network',answers:['Tell me what you are working on. There might be someone I can introduce you to.','Train your Digital and Network skills before opening a studio. Start small and deliver consistently.','That reminds me of my first week here. Nothing went to plan, but I met people who helped.']},amina:{intro:'I’ve just arrived. I’m still figuring out the buses, the food, and where to find people to study with.',skill:'Study',answers:['Want to study together sometime? It helps to have someone to compare notes with.','Try a campus lecture and join the international club. That is how I started finding my way.','Thank you for sharing that. It makes starting over feel a little less frightening.']},leo:{intro:'Training keeps me grounded. You don’t have to be good at basketball to join us.',skill:'Fitness',answers:['Come back for a workout. Consistency matters more than a perfect first session.','Keep your energy and hunger balanced before training. A walk in Nanhu Park also helps.','We all have those days. The next game is a fresh start.']}};
function talkNPC(id,topic){const c=contacts.find(c=>c[0]===id);if(!c||!Number.isInteger(topic)||topic<0||topic>2)return false;if(state.place!==c[2])return false;if(state.friendDay?.[id]===state.day){toast('Catch up with '+c[1]+' again tomorrow.');return false}if(!runningCallback&&window.ChinaLifeWorld){sceneAction({kind:'talk',x:-2+contacts.filter(p=>p[2]===c[2]).findIndex(p=>p[0]===id)*2,z:2.1,label:'Catch up with '+c[1]},()=>talkNPC(id,topic));return false}state.friendDay=state.friendDay||{};state.friendDay[id]=state.day;state.friends[id]=Math.min(100,(state.friends[id]||0)+15);state.needs.social=Math.min(100,state.needs.social+20);state.needs.fun=Math.min(100,state.needs.fun+5);gain(topic===1?dialogue[id].skill:'Social',20);advance(45);finish(c[1]+': '+dialogue[id].answers[topic]);return true}
function personScreen(id){const c=contacts.find(c=>c[0]===id);if(!c){const p=L.find(p=>p[0]===state.place);screen('Welcome to '+p[1],'Venue host · simulated character','<p>Make yourself comfortable. You can find today’s activities below.</p>'+p[7].map((a,i)=>action('hostAct'+i,a[0],a[1])).join(''));p[7].forEach((a,i)=>$('hostAct'+i).onclick=()=>activity(p,i));return}const d=dialogue[id],here=state.place===c[2],done=state.friendDay?.[id]===state.day;screen(c[1],c[3]+' · Bond '+(state.friends[id]||0)+'/100','<blockquote class="npc-quote">'+d.intro+'</blockquote>'+(state.friends[id]>=60?'<p>You are close friends. '+c[1]+' is glad to see you.</p>':'')+(here?['Ask about their day','Ask for local advice','Share a story from home'].map((t,i)=>action('topic'+i,done?'Talked today':t,'45 minutes · friendship and skill growth')).join(''):action('meetTravel','Go and meet '+c[1],L.find(p=>p[0]===c[2])[1])));if(here)[0,1,2].forEach(i=>{$('topic'+i).disabled=done;$('topic'+i).onclick=()=>{if(talkNPC(id,i))screen(c[1],'Bond '+state.friends[id]+'/100 · conversation complete','<blockquote class="npc-quote">'+d.answers[i]+'</blockquote>'+action('backPeople','Back to people','Catch up again tomorrow'));if($('backPeople'))$('backPeople').onclick=peopleScreen}});else $('meetTravel').onclick=()=>{$('activityDialog').close();select(c[2])}}

const drivingState=()=>state.driving||{lessons:0,licensed:false};
function drivingScreen(){const d=drivingState();screen('🚘 Driving school',d.licensed?'Licence earned · you can now buy and drive a car':'Learn to drive before buying a car.',d.lessons<3?action('drivingLesson','Take driving lesson','30 minutes · ¥120 · '+d.lessons+'/3 completed'):''+(d.lessons>=3&&!d.licensed?action('drivingExam','Take driving test','Pass the road test and earn your licence'):'')+(d.licensed?action('carShop','Buy a car','Choose a personal car for city travel'):'')+(d.licensed?action('carGarage','My car','View your owned vehicle'):'')+'<p class="journal-item">Cars remain personal property tied to your account.</p>');if($('drivingLesson'))$('drivingLesson').onclick=()=>{if(state.money<120)return earnScreen('You need ¥120 for a lesson.');state.money-=120;state.driving={...d,lessons:d.lessons+1};advance(30);finish('Driving lesson '+state.driving.lessons+'/3 complete.')};if($('drivingExam'))$('drivingExam').onclick=()=>{state.driving={...d,licensed:true};state.xp+=30;finish('You passed the driving test and earned your licence.')};if($('carShop'))$('carShop').onclick=()=>storeScreen('cars',null);if($('carGarage'))$('carGarage').onclick=()=>storeScreen('mine',garage().active)}
const transport=[['walkTravel',0,45,8,'Walk','walk'],['bikeTravel',2,25,4,'Shared bike','bike'],['metroTravel',4,20,2,'Metro','metro'],['busTravel',2,30,2,'Bus','bus'],['cabTravel',25,10,0,'Cab','cab'],['didiEconomyTravel',18,12,0,'DiDi Economy','didi-economy'],['didiPremiumTravel',38,8,0,'DiDi Premium','didi-premium']];
function travelScreen(id){const target=L.find(p=>p[0]===id),rides=[...carRide(),...transport];screen('Go to '+target[1],'Choose your ride. Game fares use virtual yuan.',rides.map(t=>action(t[0],t[4]+' · '+(t[1]?'¥'+t[1]:'free'),t[2]+' minutes · '+(t[3]?'uses '+t[3]+' energy':'no energy cost'))).join(''));$('activityDialog').classList.add('travel-sheet');rides.forEach(t=>$(t[0]).onclick=()=>{if(t[6]==='licence')return screen('🚘 Licence needed','You own a car, but you need a driving licence before you can drive it in the city. Three lessons and a test at the driving school.',action('getLicence','Go to driving school','Lessons are ¥120 each · then take the test'))||($('getLicence').onclick=drivingScreen);if(t[1]>0&&state.money<t[1])return earnScreen('Not enough money.');const slowHome=id==='home'&&t[1]===0&&state.needs.energy<t[3];if(state.needs.energy<t[3]&&!slowHome)return toast('Choose transport or rest first.');if(!runningCallback&&window.ChinaLifeWorld){const commit=$(t[0]).onclick;const mode=t[5];return window.ChinaLifeWorld.journey({from:state.place,to:id,mode,label:'To '+target[1]},()=>{runningCallback=true;try{commit()}finally{runningCallback=false}})}state.money-=t[1];state.needs.energy=Math.max(0,state.needs.energy-t[3]);advance(slowHome?90:t[2]);$('activityDialog').close();arrive(id);finish('Arrived at '+target[1]+'.')})}
function tripScreen(){const cities=Object.entries(cityData).map(([name,c],i)=>[name,c,i]).filter(([name])=>isOpen(name));screen('Choose your city','Travel changes your playable map. Fares and journey times are fictional game values. Your furnished apartment is available in every city.',action('openFlights','Book a flight','Visit the airport and choose your destination')+'<div class="city-picker">'+cities.map(([name,c,i])=>action('trip-'+i,c.han+' · '+name+(state.city===name?' · Here':isOpen(name)?'':' · Coming soon')+(window.ChinaLifeCloud?.online?' · '+(window.ChinaLifeCloud.online.cities[name]||0)+' online':''),isOpen(name)?c.tag+' · '+(state.city===name?'Explore this city':'¥'+c.fare+' · '+c.hours+'h'):'We are building '+name+'. Shenyang is open now.')).join('')+'</div><p class="map-note">These are game maps. Unnamed businesses, restaurants and churches are fictional venues.</p>');$('openFlights').onclick=airportScreen;cities.forEach(([name,c,i])=>$('trip-'+i).onclick=()=>{if(!isOpen(name))return toast(name+' is coming soon. Keep exploring Shenyang.');if(state.city===name){$('activityDialog').close();window.ChinaLifeWorld?.map();return}if(state.money<c.fare)return earnScreen('Not enough money to travel.');state.money-=c.fare;advance(c.hours*60);state.city=name;state.place='station';selected='station';applyCity();state.needs.fun=Math.min(100,state.needs.fun+20);if(name!=='Shenyang'&&!state.trips.includes(name)){state.trips.push(name);state.xp+=60}if(!state.visited.includes('station'))state.visited.push('station');$('activityDialog').close();finish('You arrived in '+name+'. Explore your new city.');window.ChinaLifeWorld?.map()})}
