 '<h3>😴 Sleep & freshen up</h3>'+action('homeRest','🛏 Sleep until morning','Wake up at 08:00 · restores energy')+action('homeNap','😴 Take a nap','3 hours · restores energy')+action('homeShower','🚿 Take a shower','30 minutes · restores hygiene')+action('homeToilet','🚽 Use the toilet','15 minutes · restores bladder')
