function estateScreen(id){const h=cityContent.estates.find(h=>h.id===id);if(!h)return;const owned=state.ownedHomes.includes(id);screen(h.name,homeInteriors[h.type].features, '<p>'+escapeHTML(homeInteriors[h.type].title)+' · furnished residence</p><p>¥'+h.price.toLocaleString()+' · '+(owned?'Owned':'Available to buy')+'</p>'+action('estateBuy',owned?'Use as your home':'Buy this home',owned?'Set this as your Home destination':'Purchase this city address')+action('estatePortfolio','Your homes','View every home you own'));$('estateBuy').onclick=()=>{if(state.city!=='Shenyang')return toast('Travel to Shenyang before buying or selecting this address.');if(window.ChinaLifeWorld?.busy)return toast('Finish your current action first.');if(!state.ownedHomes.includes(id)){if(state.money<h.price)return earnScreen('You need ¥'+(h.price-state.money).toLocaleString()+' more for this home.');state.money-=h.price;state.ownedHomes.push(id)}state.activeHome=id;if(state.city==='Shenyang'&&isResidence(state.place))arrive(id);finish('Your home is now '+h.name+'.');estateScreen(id)};if(owned){$('activityContent').insertAdjacentHTML('beforeend',action('estateGoHome','Go to this home','Choose transport and enter your private residence'));$('estateGoHome').onclick=()=>{if(state.city!=='Shenyang')return toast('Travel to Shenyang to enter this home.');state.activeHome=id;save();homeRoute(id)}}$('estatePortfolio').onclick=homesScreen}
function homesScreen(){const city=state.city,estates=city==='Shenyang'?cityContent.estates:[],owned=state.propertyPortfolio[city]||[];screen('Your homes in '+escapeHTML(city),'Choose an owned home or browse an available address.',Object.entries(state.propertyPortfolio).filter(([other])=>other!==city).flatMap(([other,types])=>types.map(type=>'<p class="journal-item">🏠 '+escapeHTML(other)+' · '+escapeHTML(catalog.properties.find(h=>h.id===type)?.name||type)+' · Travel to this city to use this home</p>')).join('')+owned.map(type=>action('portfolio-'+type,escapeHTML(homeTiers().find(h=>h.id===type)?.name||type)+' · Owned','Use this home and choose transport')).join('')+action('browseCityHomes','Browse home types','Apartments, townhouses and premium homes in '+escapeHTML(city))+estates.map(h=>action('estate-'+h.id,escapeHTML(h.name)+(state.ownedHomes.includes(h.id)?' · Owned':''),h.type+' · ¥'+h.price.toLocaleString()+(state.activeHome===h.id?' · Your home':''))).join(''));$('browseCityHomes').onclick=()=>shopScreen('properties','apartment');for(const type of owned)$('portfolio-'+type).onclick=()=>{if(state.city!==city)return homesScreen();if(window.ChinaLifeWorld?.busy)return toast('Finish your current action first.');state.properties[city]=type;state.activeHome=null;save();render();homeRoute('home')};for(const h of estates)$('estate-'+h.id).onclick=()=>estateScreen(h.id)}
const isResidence=id=>id==='home'||(state.ownedHomes||[]).includes(id),homeAddress=()=>state.city==='Shenyang'&&(state.ownedHomes||[]).includes(state.activeHome)?state.activeHome:'home';
function homeType(id=state.place){const visit=window.ChinaLifeHomeVisits?.current;if(visit&&visit.place===id&&visit.city===state.city){const estate=cityContent.estates.find(h=>h.id===id);return estate?.type||visit.home.properties?.[state.city]||'rental'}const h=cityContent.estates.find(h=>h.id===id);return h?.type||state.properties?.[state.city]||'rental'}
let shopMode='furniture',shopItem='bed',shopColor='#16897b';
function shopScreen(mode=shopMode,id=shopItem){const purchaseCity=state.city;shopMode=mode;const items=mode==='properties'?homeTiers():catalog.furniture;shopItem=items.some(f=>f.id===id)?id:items[0].id;const item=items.find(f=>f.id===shopItem),owned=mode==='properties'?(state.propertyPortfolio[state.city]||[]).includes(item.id):state.upgrades.includes(item.id);shopColor=state.furnitureColors[item.id]||shopColor;screen('Make room for your life','Virtual furniture and personal game homes. Purchases are saved with your character.',action('shopHomes','My homes & city addresses','Browse your portfolio and homes around Shenyang')+action('shopFortune','Discover major opportunities','Earn larger rewards through progression')+'<div class="shop-tabs"><button id="shopFurniture" class="'+(mode==='furniture'?'active':'')+'">Furniture</button><button id="shopProperties" class="'+(mode==='properties'?'active':'')+'">Homes in '+state.city+'</button></div><div class="shop-preview"><div id="productPreview" aria-label="Three-dimensional product preview"></div><button id="rotateProduct">Rotate preview ↻</button></div><div class="shop-product"><div><h3>'+item.name+'</h3><p>'+item.detail+'</p></div><strong>¥'+item.price.toLocaleString()+'</strong></div>'+(mode==='furniture'?'<div class="finish-picker">'+[['#16897b','Teal'],['#426dba','Blue'],['#d6a362','Sand']].map(([c,name])=>'<button data-finish="'+c+'" class="'+(shopColor===c?'active':'')+'">'+name+'</button>').join('')+'</div>':'')+'<button id="shopBuy" class="primary-btn shop-buy">'+(owned?(mode==='furniture'?'Apply this finish':'Use this home'):'Buy '+item.name+' · ¥'+item.price.toLocaleString())+'</button><div class="shop-grid">'+items.map(f=>'<button class="shop-card '+(f.id===item.id?'selected':'')+'" data-item="'+f.id+'"><canvas data-product="'+f.id+'" width="240" height="160" aria-label="'+f.name+' preview"></canvas><b>'+f.name+'</b><span>¥'+f.price.toLocaleString()+(mode==='furniture'&&state.upgrades.includes(f.id)?' · Owned':'')+'</span></button>').join('')+'</div><p class="map-note">Furniture is installed in fixed room positions. Home ownership removes rent in this city. Each home type is purchased once. Switch between your owned home types for free.</p>');$('shopHomes').onclick=homesScreen;$('shopFortune').onclick=fortuneScreen;$('shopFurniture').onclick=()=>shopScreen('furniture','bed');$('shopProperties').onclick=()=>shopScreen('properties','apartment');$('activityContent').querySelectorAll('[data-item]').forEach(b=>b.onclick=()=>shopScreen(mode,b.dataset.item));$('activityContent').querySelectorAll('[data-finish]').forEach(b=>b.onclick=()=>{shopColor=b.dataset.finish;previewShop();b.parentNode.querySelectorAll('button').forEach(x=>x.classList.toggle('active',x===b))});$('rotateProduct').onclick=()=>window.ChinaLifePreview?.rotate();$('shopBuy').disabled=false;$('shopBuy').onclick=()=>{if(state.city!==purchaseCity)return shopScreen(mode,item.id);if(mode==='properties'&&window.ChinaLifeWorld?.busy)return toast('Finish your current action first.');if(mode==='furniture'){if(!state.upgrades.includes(item.id)){if(state.money<item.price)return earnScreen('Not enough money.');state.money-=item.price;state.upgrades.push(item.id)}state.furnitureColors[item.id]=shopColor;finish(item.name+' is ready in your home.')}else{if(!(state.propertyPortfolio[state.city]||[]).includes(item.id)){if(state.money<item.price)return earnScreen('Not enough money.');state.money-=item.price;(state.propertyPortfolio[state.city]||= []).push(item.id)}state.properties[state.city]=item.id;state.activeHome=null;if(isResidence(state.place))arrive('home');finish('You now own a '+item.name.toLowerCase()+' in '+state.city+'.')}shopScreen(mode,item.id)};if(mode==='properties'&&owned){$('activityContent').insertAdjacentHTML('beforeend',action('shopGoHome','Go to this home','Choose transport and enter your private residence'));$('shopGoHome').onclick=()=>{if(state.city!==purchaseCity)return homesScreen();if(window.ChinaLifeWorld?.busy)return toast('Finish your current action first.');state.properties[purchaseCity]=item.id;state.activeHome=null;save();homeRoute('home')}}previewShop()}
function previewShop(){window.dispatchEvent(new CustomEvent('chinalife:preview',{detail:{mode:shopMode,id:shopItem,color:shopColor}}))}
function flightQuote(from,to){const grid={Shenyang:[6,1],Harbin:[6,0],Beijing:[4,2],Shanghai:[6,4],Guangzhou:[3,6],Shenzhen:[4,6],Chengdu:[1,4]},a=grid[from],b=grid[to],distance=Math.hypot(a[0]-b[0],a[1]-b[1]);return {fare:Math.round((200+distance*140)/10)*10,hours:Math.max(2,Math.ceil(distance*.7))}}
function airportScreen(){if(state.place!=='airport'){screen('Flights from '+state.city,'Visit the airport to book, board or cancel a game flight.',action('goAirport','Travel to the airport',state.city+' Airport'));$('goAirport').onclick=()=>{$('activityDialog').close();select('airport')};return}const destinations=Object.entries(cityData).filter(([city])=>city!==state.city).map(([city,c],i)=>[city,c,i]).filter(([city])=>isOpen(city));screen(state.city+' Airport','Choose a destination. Booking charges virtual yuan; boarding completes the journey. These are game flights, not real airline bookings.','<h3>Your tickets</h3>'+state.flightBookings.filter(f=>f.status==='booked').map(f=>'<div class="boarding-pass"><b>'+f.from+' ✈ '+f.to+'</b><span>CL-'+f.id.toUpperCase()+' · ¥'+f.fare+' · '+f.hours+'h</span><button data-board="'+f.id+'">Board flight</button><button data-cancel="'+f.id+'">Cancel · 90% refund</button></div>').join('')+action('scenicFlight','Scenic flight over '+state.city+' · ¥180','1 hour · see the skyline from the air and land back here')+'<h3>Departures from '+state.city+'</h3>'+(!destinations.length?'<p>No other cities are open for flights yet.</p>':'')+destinations.map(([city,c,i])=>action('flight-'+i,city+(isOpen(city)?' · Economy':' · Coming soon'),isOpen(city)?'¥'+flightQuote(state.city,city).fare+' · '+flightQuote(state.city,city).hours+' hours in game':'Flights open when '+city+' launches')).join(''));$('scenicFlight').onclick=()=>{if(state.money<180)return toast('You need ¥180 for a scenic flight.');const flown=state,home=state.city;$('activityDialog').close();const landed=()=>{if(state!==flown)return;state.money-=180;advance(60);state.needs.fun=Math.min(100,state.needs.fun+30);state.xp+=15;finish('You flew over '+home+' and landed back at the airport.');checkSecrets('jet-setter');window.ChinaLifeWorld?.venue('airport')};if(window.ChinaLifeWorld?.flight)window.ChinaLifeWorld.flight({label:'Scenic flight over '+home,scenic:true},landed);else landed()};destinations.forEach(([city,c,i])=>$('flight-'+i).onclick=()=>{if(!isOpen(city))return toast(city+' is coming soon.');const fare=flightQuote(state.city,city).fare;if(state.money<fare)return earnScreen('Not enough money.');if(state.flightBookings.filter(f=>f.status==='booked').length>=3)return toast('You can hold three active tickets. Board or cancel one first.');state.money-=fare;state.flightBookings.push({id:Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,7),from:state.city,to:city,fare,hours:flightQuote(state.city,city).hours,day:state.day,status:'booked'});if(state.flightBookings.length>20)state.flightBookings=state.flightBookings.slice(-20);finish('Ticket booked: '+state.city+' to '+city+'.');airportScreen()});$('activityContent').querySelectorAll('[data-board]').forEach(b=>b.onclick=()=>{const f=state.flightBookings.find(f=>f.id===b.dataset.board);if(!f||f.status!=='booked')return;if(f.from!==state.city)return toast('This flight departs from '+f.from+'.');if(!isOpen(f.to))return toast('This city is not open. You can cancel your ticket for a refund.');const flown=state;
 // The city changes mid-flight so the plane can be seen landing in the destination.
 const arrive=()=>{if(state!==flown||f.status!=='booked')return;f.status='flown';advance(f.hours*60);state.city=f.to;state.place='airport';selected='airport';applyCity();if(f.to!=='Shenyang'&&!state.trips.includes(f.to)){state.trips.push(f.to);state.xp+=60}if(!state.visited.includes('airport'))state.visited.push('airport');save()};
 const landed=()=>{if(state!==flown)return;arrive();finish('Landed in '+f.to+'. Welcome to your next chapter.');window.ChinaLifeWorld?.venue('airport')};
 $('activityDialog').close();if(window.ChinaLifeWorld?.flight)return window.ChinaLifeWorld.flight({label:'Flight to '+f.to,arrive},landed);landed()});$('activityContent').querySelectorAll('[data-cancel]').forEach(b=>b.onclick=()=>{const f=state.flightBookings.find(f=>f.id===b.dataset.cancel);if(!f||f.status!=='booked')return;f.status='cancelled';state.money+=Math.floor(f.fare*.9);finish('Flight cancelled. 90% of the virtual fare was refunded.');airportScreen()})}
