function clientTrust(b,id){return b.clientTrust?.[id]??(b.clientHistory||[]).filter(h=>h.client===id&&h.rating>=4).length}
function contractFeedback(text){if($('contractFeedback')&&$('activityDialog').open)$('contractFeedback').textContent=text;else toast(text)}
function acceptContract(id){const b=state.business,c=studioCatalog?.clients.find(c=>c.id===id);if(!b||!c||b.activeContract)return false;if(b.level<c.level||(state.skills[c.skill]||1)<c.required){contractFeedback('Requires studio level '+c.level+' and '+c.skill+' '+c.required+'.');return false}const completed=clientTrust(b,id);b.activeContract={client:id,acceptedDay:state.day,dueDay:Math.min(36500,state.day+c.days),fee:Math.round(c.fee*(completed>=2?1+studioCatalog.repeatBonus:1))};save();renderStudioContracts();contractFeedback('Accepted. Visit '+L.find(p=>p[0]==='business')[1]+' and deliver by day '+b.activeContract.dueDay+'.');return true}
